<section class="portal-metrics" aria-label="Account summary"><div><span>Requests</span><strong><?= $requestCount ?></strong></div><div><span>Quotes</span><strong><?= $quoteCount ?></strong></div><div><span>Projects</span><strong><?= $projectCount ?></strong></div></section>
