    <section class="portal-list"><div class="portal-section-heading"><h2>Quotes</h2><span>Sent by the studio</span></div><?php if ($quotes === []): ?><p class="portal-empty">No quotes are available yet.</p><?php else: ?><?php foreach ($quotes as $quote): ?><a class="portal-list-row" href="/portal/quotes/<?= (int) $quote['id'] ?>"><span><strong><?= esc($quote['quote_number']) ?></strong><small><?= esc($quote['currency_code']) ?> <?= esc(number_format((float) $quote['total'], 2)) ?></small></span><span class="portal-status"><?= esc(\App\Models\QuoteModel::STATUSES[$quote['status']] ?? ucfirst($quote['status'])) ?></span></a><?php endforeach ?><?php endif ?></section>
    <section class="portal-list portal-list-wide"><div class="portal-section-heading"><h2>Quote requests</h2><span>Your submitted briefs</span></div><?php if ($requests === []): ?><p class="portal-empty">No quote requests are linked to this account.</p><?php else: ?><?php foreach ($requests as $request): ?><a class="portal-list-row" href="/portal/requests/<?= (int) $request['id'] ?>"><span><strong><?= esc($request['project_summary']) ?></strong><small><?= esc($request['reference_number']) ?> &middot; <?= esc(substr((string) $request['created_at'], 0, 10)) ?></small></span><span class="portal-status"><?= esc(\App\Models\QuoteRequestModel::STATUSES[$request['status']] ?? ucfirst($request['status'])) ?></span></a><?php endforeach ?><?php endif ?></section>
</div>
